-- =============================================================================
-- LENS REGISTRY - Safe Version (handles existing data)
-- =============================================================================
-- Run this if you get duplicate key errors
-- Uses ON CONFLICT to skip or update existing rows
-- =============================================================================

-- Create tables if they don't exist
CREATE TABLE IF NOT EXISTS "lens_definitions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "lens_slug" TEXT UNIQUE NOT NULL,
  "lens_name" TEXT NOT NULL,
  "lens_description" TEXT,
  "paradigm_family" TEXT,
  "language_style" TEXT,
  "cultural_origin" TEXT,
  "is_system" BOOLEAN DEFAULT TRUE,
  "is_active" BOOLEAN DEFAULT TRUE,
  "created_by" TEXT,
  "icon" TEXT,
  "color" TEXT,
  "sort_order" INTEGER DEFAULT 100,
  "notes" TEXT,
  "created_at" TIMESTAMPTZ DEFAULT NOW(),
  "updated_at" TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS "technique_lens_explanations" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "technique_id" BIGINT REFERENCES "techniques"("id") ON DELETE CASCADE,
  "lens_id" BIGINT REFERENCES "lens_definitions"("id") ON DELETE CASCADE,
  "explanation_template" TEXT NOT NULL,
  "mechanism_notes" TEXT,
  "cue_language" TEXT,
  "safety_framing" TEXT,
  "is_verified" BOOLEAN DEFAULT FALSE,
  "verified_by" TEXT,
  "created_at" TIMESTAMPTZ DEFAULT NOW(),
  "updated_at" TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE("technique_id", "lens_id")
);

CREATE TABLE IF NOT EXISTS "user_lens_preferences" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" TEXT NOT NULL,
  "lens_id" BIGINT REFERENCES "lens_definitions"("id") ON DELETE CASCADE,
  "preference_level" INTEGER DEFAULT 50,
  "is_enabled" BOOLEAN DEFAULT TRUE,
  "last_used_at" TIMESTAMPTZ,
  "use_count" INTEGER DEFAULT 0,
  "created_at" TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE("user_id", "lens_id")
);

CREATE TABLE IF NOT EXISTS "user_lens_context" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" TEXT NOT NULL,
  "context_date" DATE NOT NULL,
  "mood_state" TEXT,
  "energy_level" INTEGER,
  "receptivity" TEXT,
  "recent_lenses_used" TEXT,
  "ai_suggested_lens" TEXT,
  "ai_reasoning" TEXT,
  "override_lens" TEXT,
  "created_at" TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE("user_id", "context_date")
);

