-- Create indexes if they don't exist
CREATE INDEX IF NOT EXISTS "idx_lens_definitions_slug" ON "lens_definitions" ("lens_slug");
CREATE INDEX IF NOT EXISTS "idx_lens_definitions_active" ON "lens_definitions" ("is_active");
CREATE INDEX IF NOT EXISTS "idx_technique_lens_technique" ON "technique_lens_explanations" ("technique_id");
CREATE INDEX IF NOT EXISTS "idx_technique_lens_lens" ON "technique_lens_explanations" ("lens_id");
CREATE INDEX IF NOT EXISTS "idx_user_lens_pref_user" ON "user_lens_preferences" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_user_lens_context_user" ON "user_lens_context" ("user_id", "context_date");

-- Success message
SELECT 'Lens registry tables created/updated successfully. ' || 
       (SELECT COUNT(*) FROM lens_definitions) || ' lenses in system.' AS status;




